#include "carmesh.hpp"

// Generated by tools/s15_convert.py: S15_V (millimetres, x y z), S15_T (triangles),
// S15_P (part per triangle).
#include "gen/s15_mesh.inc"

namespace fh6 {

const char* const CAR_CREDIT = "Car model by VuckyZ (sketchfab.com/VuckyZ123), CC BY 4.0, simplified";

namespace {
CarMesh build() {
    CarMesh m;
    m.verts.reserve(S15_NV);
    for (int i = 0; i < S15_NV; i++) m.verts.push_back(V3(S15_V[i * 3] * 0.001, S15_V[i * 3 + 1] * 0.001, S15_V[i * 3 + 2] * 0.001));
    m.faces.reserve(S15_NT);
    for (int i = 0; i < S15_NT; i++) m.faces.push_back({ { S15_T[i * 3], S15_T[i * 3 + 1], S15_T[i * 3 + 2] }, S15_P[i] });
    return m;
}
} // namespace

const CarMesh& carMesh() {
    static const CarMesh m = build();
    return m;
}

} // namespace fh6
